source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
import json, os, glob

base = '/root/entrainment_gated_ft/lm_eval_clean/exp007'
results = {}

for scale in ['340m', '1.3b']:
    results[scale] = {}
    scale_dir = os.path.join(base, scale)
    for model_dir in sorted(os.listdir(scale_dir)):
        json_files = glob.glob(os.path.join(scale_dir, model_dir, '*.json'))
        for jf in json_files:
            if 'samples' not in jf:
                with open(jf) as f:
                    data = json.load(f)
                r = data.get('results', {}).get('lambada_openai', {})
                acc = r.get('acc,none', None)
                ppl = r.get('perplexity,none', None)
                results[scale][model_dir] = {'acc': acc, 'ppl': ppl}

print('=== 340M ===')
for m in sorted(results['340m'].keys()):
    d = results['340m'][m]
    print(f'{m:20s}  acc={d[\"acc\"]:.4f}  ppl={d[\"ppl\"]:.2f}')

print()
print('=== 1.3B ===')
for m in sorted(results['1.3b'].keys()):
    d = results['1.3b'][m]
    print(f'{m:20s}  acc={d[\"acc\"]:.4f}  ppl={d[\"ppl\"]:.2f}')
"

